type QuintValue =
    | Bool of bool
    | Int of int64
    | String of string
    | Tuple of QuintValue list
    | Record of (string * QuintValue) list
    | Variant of string * QuintValue option
    | List of QuintValue list
    | Set of QuintValue list
    | Map of (QuintValue * QuintValue) list

type QuintExport =
    { Id: string
      ModuleName: string
      DeclarationName: string
      Value: QuintValue }

type CatalogueEntry =
    { Id: string
      Kind: string
      ExportId: string
      Value: QuintValue }

